import React, { useState } from "react";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Alert,
} from "reactstrap";
import UserHeader from "components/Headers/UserHeader.js";

const CarbonRedemption = () => {
  const [selectedOption, setSelectedOption] = useState("");
  const [credits, setCredits] = useState(100); // Example: User starts with 100 credits
  const [message, setMessage] = useState("");

  const redemptionOptions = [
    { label: "Plant a Tree (50 Credits)", value: 50 },
    { label: "Public Transport Pass (30 Credits)", value: 30 },
    { label: "Eco-friendly Shopping Discount (20 Credits)", value: 20 },
  ];

  const handleRedemption = () => {
    if (!selectedOption) {
      setMessage("Please select a redemption option.");
      return;
    }

    const cost = redemptionOptions.find((option) => option.label === selectedOption)?.value;
    if (cost && credits >= cost) {
      setCredits(credits - cost);
      setMessage(`Successfully redeemed: ${selectedOption}! Remaining credits: ${credits - cost}`);
    } else {
      setMessage("Not enough credits for this redemption.");
    }
  };

  return (
    <>
      <UserHeader />
      <Container className="mt--7" fluid>
        <Row>
          <Col xl="8" className="offset-xl-2">
            <Card className="bg-secondary shadow">
              <CardHeader className="bg-white border-0">
                <h3 className="mb-0">Redeem Your Carbon Credits</h3>
              </CardHeader>
              <CardBody>
                <Form>
                  <h6 className="heading-small text-muted mb-4">Your Available Credits: {credits}</h6>
                  <FormGroup>
                    <label className="form-control-label">Choose a Reward</label>
                    <Input
                      type="select"
                      onChange={(e) => setSelectedOption(e.target.value)}
                      value={selectedOption}
                    >
                      <option value="">Select an option</option>
                      {redemptionOptions.map((option) => (
                        <option key={option.label} value={option.label}>
                          {option.label}
                        </option>
                      ))}
                    </Input>
                  </FormGroup>
                  {message && <Alert color={message.includes("Success") ? "success" : "danger"}>{message}</Alert>}
                  <Button color="primary" onClick={handleRedemption}>Redeem</Button>
                </Form>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default CarbonRedemption;
